const d = $json.body || $json;
const nombre = (d.usuario && (d.usuario.displayname || d.usuario.username)) || (d.usuario && d.usuario.email) || 'Cliente';
const email = (d.usuario && d.usuario.email) || '';
const fecha = d.creado_el ? new Date(d.creado_el.replace(' ', 'T')).toLocaleString() : new Date().toLocaleString();
let filas = '';
let subtotal = 0;
(d.items || []).forEach(function(it){
  const line = Number(it.precio) * Number(it.cantidad);
  subtotal += line;
  filas += '<tr>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;color:#1f2937;font-weight:600;">' + it.nombre + '</td>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:center;color:#6b7280;">' + it.cantidad + '</td>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:right;color:#6b7280;">$' + Number(it.precio).toFixed(2) + '</td>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:right;color:#111827;font-weight:600;">$' + line.toFixed(2) + '</td>'
    + '</tr>';
});
if(!filas){ filas = '<tr><td colspan="4" style="padding:12px;text-align:center;color:#6b7280;">Sin items</td></tr>'; }
const total = Number(d.total || subtotal).toFixed(2);
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:Helvetica,Arial,sans-serif;">'
+ '<div style="max-width:600px;margin:24px auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;">'
+ '<div style="background:linear-gradient(135deg,#111827,#1f2937);padding:24px 28px;">'
+ '<div style="font-size:22px;font-weight:800;letter-spacing:1px;color:#fbbf24;">PIXELVAULT</div>'
+ '<div style="font-size:12px;color:#9ca3af;margin-top:4px;letter-spacing:2px;text-transform:uppercase;">Tu pedido confirmado</div>'
+ '</div>'
+ '<div style="padding:24px 28px;">'
+ '<div style="font-size:18px;font-weight:700;color:#111827;margin-bottom:4px;">Gracias por tu compra, ' + nombre + '!</div>'
+ '<div style="font-size:13px;color:#6b7280;margin-bottom:20px;">Hemos recibido tu pedido y lo estaremos preparando. Guarda este correo como comprobante.</div>'
+ '<table style="width:100%;border-collapse:collapse;margin-bottom:20px;">'
+ '<thead><tr style="background:#f9fafb;">'
+ '<th style="padding:10px 12px;text-align:left;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:1px;border-bottom:2px solid #e5e7eb;">Producto</th>'
+ '<th style="padding:10px 12px;text-align:center;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:1px;border-bottom:2px solid #e5e7eb;">Cant.</th>'
+ '<th style="padding:10px 12px;text-align:right;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:1px;border-bottom:2px solid #e5e7eb;">P. Unit.</th>'
+ '<th style="padding:10px 12px;text-align:right;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:1px;border-bottom:2px solid #e5e7eb;">Subtotal</th>'
+ '</tr></thead>'
+ '<tbody>' + filas + '</tbody>'
+ '</table>'
+ '<div style="background:#f9fafb;border-radius:8px;padding:14px 18px;display:flex;justify-content:space-between;align-items:center;">'
+ '<span style="font-size:13px;color:#6b7280;letter-spacing:1px;text-transform:uppercase;">Total pagado</span>'
+ '<span style="font-size:20px;font-weight:800;color:#111827;">$' + total + '</span>'
+ '</div>'
+ '<div style="margin-top:20px;font-size:12px;color:#9ca3af;">'
+ '<div><strong style="color:#6b7280;">Codigo de pedido:</strong> ' + d.codigo + '</div>'
+ '<div><strong style="color:#6b7280;">Fecha:</strong> ' + fecha + '</div>'
+ '</div>'
+ '</div>'
+ '<div style="background:#111827;padding:16px 28px;">'
+ '<div style="font-size:11px;color:#9ca3af;">PIXELVAULT - Tu tienda de gaming de confianza. 2026</div>'
+ '</div>'
+ '</div></body></html>';
return { json: { email: email, subject: 'PIXELVAULT - Confirmacion de pedido ' + d.codigo, html: html, codigo: d.codigo } };
